mapper.update:
UPDATE work_orders
title = #{title}, description = #{description}, type = #{type}, priority = #{priority}, status = #{status}, handler_id = #{handlerId}, result = #{result}, tags = #{tags}, summary = #{summary}, session_id = #{sessionId}, matching_skill = #{matchingSkill}, dispatch_confidence = #{dispatchConfidence}, biz_tag = #{bizTag}, emotion_level = #{emotionLevel}, sla_deadline = #{slaDeadline}, response_deadline = #{responseDeadline}, responded_at = #{respondedAt}, sla_paused = #{slaPaused}, effective_response_seconds = #{effectiveResponseSeconds}, effective_resolution_seconds = #{effectiveResolutionSeconds}, first_responder_id = #{firstResponderId}, resolver_id = #{resolverId}, exclude_from_sla = #{excludeFromSla}, rating = #{rating}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM work_orders
WHERE first_responder_id = #{agentId}
AND exclude_from_sla = 0
AND response_deadline IS NOT NULL
AND (responded_at IS NULL OR responded_at > response_deadline)
AND create_time BETWEEN #{start} AND #{end}

SELECT AVG(effective_response_seconds) FROM work_orders
WHERE first_responder_id = #{agentId}
AND exclude_from_sla = 0
AND effective_response_seconds IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}

SELECT AVG(effective_resolution_seconds) FROM work_orders
WHERE resolver_id = #{agentId}
AND exclude_from_sla = 0
AND effective_resolution_seconds IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}

SELECT
    rating AS ratingLevel,
    COUNT(*) AS totalCount
FROM work_orders
WHERE handler_id = #{agentId}
AND rating IS NOT NULL
AND create_time BETWEEN #{start} AND #{end}

    AND type = #{workOrderType}

GROUP BY rating
ORDER BY rating DESC
